def rle_encode(s):
    parts = []
    i = 0
    n = len(s)
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        parts.append(str(j - i) + s[i])
        i = j
    return ''.join(parts)


def rle_decode(s):
    parts = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and '0' <= s[j] <= '9':
            j += 1
        if j == i:
            raise ValueError("token has no run length")
        length = int(s[i:j])
        if j >= n:
            raise ValueError("dangling length")
        ch = s[j]
        if not ('a' <= ch <= 'z' or 'A' <= ch <= 'Z'):
            raise ValueError("character is not a letter")
        if length <= 0:
            raise ValueError("run length must be positive")
        parts.append(ch * length)
        i = j + 1
    return ''.join(parts)
