def base36(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    chars = []
    while n:
        n, r = divmod(n, 36)
        chars.append(digits[r])
    return "".join(reversed(chars))
